[CmdletBinding()]
param([string]$WorkspaceRoot)
$ErrorActionPreference='Stop';if(-not $WorkspaceRoot){$WorkspaceRoot=Split-Path -Parent $PSScriptRoot}
$change=Join-Path $WorkspaceRoot 'openspec/changes/bootstrap-superdesktop-workspace';$index=Join-Path $change 'evidence/index.jsonl';$adjustments=Join-Path $change 'evidence/adjustments.jsonl'
$coverage=(Get-Content -Raw "$change/evidence/coverage.json"|ConvertFrom-Json).tasks;$records=@(Get-Content $index|?{$_}|%{$_|ConvertFrom-Json});$ids=@{};foreach($r in $records){$ids["$($r.task_id)#$($r.subcheck)"]=$true}
$artifacts=@{'bootstrap-superdesktop-workspace/1.1.2'='workspace-current-inputs.sha256';'bootstrap-superdesktop-workspace/1.1.3'='workspace-current-inputs.sha256';'bootstrap-superdesktop-workspace/1.1.4'='workspace-current-inputs.sha256';'bootstrap-superdesktop-workspace/1.2.4'='dependency-current-inputs.sha256';'bootstrap-superdesktop-workspace/1.2.5'='dependency-current-inputs.sha256';'bootstrap-superdesktop-workspace/1.2.6'='dependency-current-inputs.sha256';'bootstrap-superdesktop-workspace/2.2.2'='source-boundary-current-inputs.sha256';'bootstrap-superdesktop-workspace/2.2.4'='source-boundary-current-inputs.sha256';'bootstrap-superdesktop-workspace/2.4.1'='aggregate-contract-inputs.sha256';'bootstrap-superdesktop-workspace/2.4.2'='schema-engine.md';'bootstrap-superdesktop-workspace/2.4.3'='adjustment-graph.md';'bootstrap-superdesktop-workspace/2.4.4'='workspace-current-inputs.sha256';'bootstrap-superdesktop-workspace/2.4.5'='full-matrix.md';'bootstrap-superdesktop-workspace/2.5.1'='aggregate-contract-inputs.sha256';'bootstrap-superdesktop-workspace/2.5.6'='windows-substrate.txt'}
$stale=@();$replacement=@();foreach($taskId in $artifacts.Keys){$meta=@($coverage|?{$_.task_id -eq $taskId})[0];if(-not $meta){throw "UNKNOWN_TASK $taskId"};$base=$taskId.Split('/')[-1];$s="$taskId#2.5-final-stale";$p="$taskId#2.5-final";if($ids.ContainsKey($s)){continue};$file=$artifacts[$taskId];$path="evidence/artifacts/2.5/$file";$hash=(Get-FileHash -Algorithm SHA256 "$change/$path").Hash;$common=[ordered]@{schema_version='2.0.0';task_id=$taskId;artifact=$path;artifact_sha256=$hash;capability_id=$meta.capability_id;requirement_id=$meta.requirement_id;scenario_id=$meta.scenario_id;gates=@($meta.gates);reviewer='Workspace/Build owner';recorded_at='2026-08-14T12:00:00+08:00';procedure='2.5 final immutable manifest and lineage replacement';expected='passed';actual='passed'};$a=[ordered]@{}+$common;$a.subcheck='wave25-final-stale';$a.status='stale';$a.superseded_by=$p;$b=[ordered]@{}+$common;$b.subcheck='wave25-final';$b.status='passed';$b.replaces=$s;Add-Content -Encoding utf8 $index ($a|ConvertTo-Json -Compress);Add-Content -Encoding utf8 $index ($b|ConvertTo-Json -Compress);$stale+=$s;$replacement+=$p}
$old=@(Get-Content $adjustments|?{$_}|%{$_|ConvertFrom-Json}|?{$_.adjustment_id -eq 'B-W1-2.5-SUCCESSOR'})[0];$allStale=@($old.stale_record_ids)+$stale;$allReplacement=@($old.replacement_record_ids)+$replacement;$successor=[ordered]@{adjustment_id='B-W1-2.5-FULL-SUCCESSOR';classification='B';recorded_at='2026-08-14T12:00:00+08:00';scope='full effective corrective successor';supersedes_adjustments=@('B-W1-2.5-SUCCESSOR','B-W1-EXIT-004');stale_record_ids=$allStale;replacement_record_ids=$allReplacement;status='replacement-passed'};Add-Content -Encoding utf8 $adjustments ($successor|ConvertTo-Json -Compress)
